;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; ECS Component Registry for MSX
;; Generated by MSX Retro Game IDE
;;
;; Component type definitions and registration system
;; Based on the default components from the IDE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; Component Type IDs (must match the IDE generator)
COMP_ID_TRANSFORM       EQU 0
COMP_ID_RENDERER        EQU 1
COMP_ID_PHYSICS         EQU 2
COMP_ID_ANIMATION       EQU 3
COMP_ID_AI              EQU 4
COMP_ID_HEALTH          EQU 5
COMP_ID_COLLISION       EQU 6
COMP_ID_AIMING          EQU 7
COMP_ID_PROJECTILE      EQU 8
COMP_ID_SPAWNER         EQU 9
COMP_ID_SOUND           EQU 10
COMP_ID_POWERUP         EQU 11
COMP_ID_DIALOG          EQU 12
COMP_ID_TRIGGER         EQU 13

; Maximum number of component types
MAX_COMPONENT_TYPES     EQU 14

; Component data sizes (in bytes, excluding type and owner fields)
TRANSFORM_SIZE          EQU 8   ; x(2), y(2), rotation(2), scale(2)
RENDERER_SIZE           EQU 6   ; spriteRef(2), layer(1), visible(1), flipX(1), flipY(1)
PHYSICS_SIZE            EQU 12  ; velX(2), velY(2), accX(2), accY(2), mass(2), friction(2)
ANIMATION_SIZE          EQU 8   ; currentFrame(2), frameTime(2), frameCount(2), looping(1), playing(1)
AI_SIZE                 EQU 10  ; aiType(1), state(1), target(2), speed(2), range(2), lastAction(2)
HEALTH_SIZE             EQU 6   ; currentHealth(2), maxHealth(2), invulnerable(1), damageFlash(1)
COLLISION_SIZE          EQU 8   ; width(2), height(2), offsetX(2), offsetY(2)
AIMING_SIZE             EQU 8   ; targetEntity(2), range(2), rotSpeed(2), fieldOfView(1), active(1)
PROJECTILE_SIZE         EQU 10  ; damage(2), speed(2), maxDistance(2), lifetime(2), bounces(1), piercing(1)
SPAWNER_SIZE            EQU 10  ; templateId(2), spawnRate(2), maxSpawns(2), currentSpawns(2), active(1), triggered(1)
SOUND_SIZE              EQU 6   ; soundRef(2), volume(1), looping(1), playing(1), channel(1)
POWERUP_SIZE            EQU 8   ; powerupType(1), value(2), duration(2), permanent(1), collected(1), respawnTime(1)
DIALOG_SIZE             EQU 8   ; textRef(2), active(1), currentChar(2), speed(1), autoClose(1), closeDelay(1)
TRIGGER_SIZE            EQU 10  ; triggerType(1), active(1), triggered(1), resetTime(2), targetEntity(2), actionData(3)

; Component size lookup table
COMPONENT_SIZES:
    DB TRANSFORM_SIZE
    DB RENDERER_SIZE
    DB PHYSICS_SIZE
    DB ANIMATION_SIZE
    DB AI_SIZE
    DB HEALTH_SIZE
    DB COLLISION_SIZE
    DB AIMING_SIZE
    DB PROJECTILE_SIZE
    DB SPAWNER_SIZE
    DB SOUND_SIZE
    DB POWERUP_SIZE
    DB DIALOG_SIZE
    DB TRIGGER_SIZE

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Component update function pointers
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
COMPONENT_UPDATE_FUNCTIONS:
    DW UPDATE_TRANSFORM     ; COMP_ID_TRANSFORM
    DW UPDATE_RENDERER      ; COMP_ID_RENDERER
    DW UPDATE_PHYSICS       ; COMP_ID_PHYSICS
    DW UPDATE_ANIMATION     ; COMP_ID_ANIMATION
    DW UPDATE_AI            ; COMP_ID_AI
    DW UPDATE_HEALTH        ; COMP_ID_HEALTH
    DW UPDATE_COLLISION     ; COMP_ID_COLLISION
    DW UPDATE_AIMING        ; COMP_ID_AIMING
    DW UPDATE_PROJECTILE    ; COMP_ID_PROJECTILE
    DW UPDATE_SPAWNER       ; COMP_ID_SPAWNER
    DW UPDATE_SOUND         ; COMP_ID_SOUND
    DW UPDATE_POWERUP       ; COMP_ID_POWERUP
    DW UPDATE_DIALOG        ; COMP_ID_DIALOG
    DW UPDATE_TRIGGER       ; COMP_ID_TRIGGER

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Get component data size
;; Input: A = Component type ID
;; Output: A = Size in bytes (0 if invalid type)
;; Destroys: HL
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
GET_COMPONENT_SIZE:
    CP MAX_COMPONENT_TYPES
    JR NC, GET_COMPONENT_SIZE_INVALID
    
    LD HL, COMPONENT_SIZES
    ADD A, L
    LD L, A
    JR NC, GET_COMPONENT_SIZE_NO_CARRY
    INC H
GET_COMPONENT_SIZE_NO_CARRY:
    LD A, (HL)
    RET

GET_COMPONENT_SIZE_INVALID:
    XOR A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Validate component data
;; Input: A = Component type ID, HL = Component data pointer
;; Output: A = 1 if valid, 0 if invalid
;; Destroys: BC, DE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
VALIDATE_COMPONENT:
    CP MAX_COMPONENT_TYPES
    JR NC, VALIDATE_COMPONENT_INVALID
    
    ; Add specific validation logic per component type here
    ; For now, just check if the type ID is valid
    LD A, 1
    RET

VALIDATE_COMPONENT_INVALID:
    XOR A
    RET

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Initialize component with default values
;; Input: A = Component type ID, HL = Component data pointer
;; Output: None
;; Destroys: BC, DE
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
INIT_COMPONENT_DEFAULTS:
    CP MAX_COMPONENT_TYPES
    RET NC                  ; Invalid component type
    
    ; Jump to specific initialization based on component type
    PUSH HL
    LD HL, COMPONENT_INIT_TABLE
    ADD A, A                ; * 2 for word addresses
    ADD A, L
    LD L, A
    JR NC, INIT_COMPONENT_NO_CARRY
    INC H
INIT_COMPONENT_NO_CARRY:
    LD E, (HL)
    INC HL
    LD D, (HL)
    POP HL
    
    ; Call initialization function
    PUSH DE
    RET                     ; Jump to initialization function

COMPONENT_INIT_TABLE:
    DW INIT_TRANSFORM
    DW INIT_RENDERER
    DW INIT_PHYSICS
    DW INIT_ANIMATION
    DW INIT_AI
    DW INIT_HEALTH
    DW INIT_COLLISION
    DW INIT_AIMING
    DW INIT_PROJECTILE
    DW INIT_SPAWNER
    DW INIT_SOUND
    DW INIT_POWERUP
    DW INIT_DIALOG
    DW INIT_TRIGGER

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;; Component initialization functions
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

INIT_TRANSFORM:
    ; x(2), y(2), rotation(2), scale(2)
    XOR A
    LD (HL), A              ; x low
    INC HL
    LD (HL), A              ; x high
    INC HL
    LD (HL), A              ; y low
    INC HL
    LD (HL), A              ; y high
    INC HL
    LD (HL), A              ; rotation low
    INC HL
    LD (HL), A              ; rotation high
    INC HL
    LD (HL), 1              ; scale low = 1
    INC HL
    LD (HL), A              ; scale high = 0
    RET

INIT_RENDERER:
    ; spriteRef(2), layer(1), visible(1), flipX(1), flipY(1)
    XOR A
    LD (HL), A              ; spriteRef low
    INC HL
    LD (HL), A              ; spriteRef high
    INC HL
    LD (HL), A              ; layer = 0
    INC HL
    LD (HL), 1              ; visible = true
    INC HL
    LD (HL), A              ; flipX = false
    INC HL
    LD (HL), A              ; flipY = false
    RET

INIT_PHYSICS:
    ; velX(2), velY(2), accX(2), accY(2), mass(2), friction(2)
    XOR A
    LD B, 10                ; 10 bytes to clear
INIT_PHYSICS_LOOP:
    LD (HL), A
    INC HL
    DJNZ INIT_PHYSICS_LOOP
    
    ; Set default mass to 1
    DEC HL
    DEC HL
    DEC HL
    DEC HL
    LD (HL), 1              ; mass low = 1
    RET

INIT_ANIMATION:
    ; currentFrame(2), frameTime(2), frameCount(2), looping(1), playing(1)
    XOR A
    LD (HL), A              ; currentFrame low
    INC HL
    LD (HL), A              ; currentFrame high
    INC HL
    LD (HL), A              ; frameTime low
    INC HL
    LD (HL), A              ; frameTime high
    INC HL
    LD (HL), 1              ; frameCount low = 1
    INC HL
    LD (HL), A              ; frameCount high
    INC HL
    LD (HL), A              ; looping = false
    INC HL
    LD (HL), A              ; playing = false
    RET

INIT_AI:
    ; aiType(1), state(1), target(2), speed(2), range(2), lastAction(2)
    XOR A
    LD (HL), A              ; aiType = 0 (none)
    INC HL
    LD (HL), A              ; state = 0 (idle)
    INC HL
    LD B, 8                 ; Clear remaining 8 bytes
INIT_AI_LOOP:
    LD (HL), A
    INC HL
    DJNZ INIT_AI_LOOP
    RET

INIT_HEALTH:
    ; currentHealth(2), maxHealth(2), invulnerable(1), damageFlash(1)
    LD (HL), 100            ; currentHealth low = 100
    INC HL
    XOR A
    LD (HL), A              ; currentHealth high = 0
    INC HL
    LD (HL), 100            ; maxHealth low = 100
    INC HL
    LD (HL), A              ; maxHealth high = 0
    INC HL
    LD (HL), A              ; invulnerable = false
    INC HL
    LD (HL), A              ; damageFlash = 0
    RET

INIT_COLLISION:
    ; width(2), height(2), offsetX(2), offsetY(2)
    LD (HL), 16             ; width low = 16
    INC HL
    XOR A
    LD (HL), A              ; width high = 0
    INC HL
    LD (HL), 16             ; height low = 16
    INC HL
    LD (HL), A              ; height high = 0
    INC HL
    LD (HL), A              ; offsetX low = 0
    INC HL
    LD (HL), A              ; offsetX high = 0
    INC HL
    LD (HL), A              ; offsetY low = 0
    INC HL
    LD (HL), A              ; offsetY high = 0
    RET

INIT_AIMING:
    ; targetEntity(2), range(2), rotSpeed(2), fieldOfView(1), active(1)
    XOR A
    LD B, 8                 ; Clear all 8 bytes
INIT_AIMING_LOOP:
    LD (HL), A
    INC HL
    DJNZ INIT_AIMING_LOOP
    RET

INIT_PROJECTILE:
    ; damage(2), speed(2), maxDistance(2), lifetime(2), bounces(1), piercing(1)
    LD (HL), 10             ; damage low = 10
    INC HL
    XOR A
    LD (HL), A              ; damage high = 0
    INC HL
    LD (HL), 50             ; speed low = 50
    INC HL
    LD (HL), A              ; speed high = 0
    INC HL
    LD (HL), 0xFF           ; maxDistance low = 255
    INC HL
    LD (HL), A              ; maxDistance high = 0
    INC HL
    LD (HL), 60             ; lifetime low = 60 frames
    INC HL
    LD (HL), A              ; lifetime high = 0
    INC HL
    LD (HL), A              ; bounces = 0
    INC HL
    LD (HL), A              ; piercing = false
    RET

INIT_SPAWNER:
    ; templateId(2), spawnRate(2), maxSpawns(2), currentSpawns(2), active(1), triggered(1)
    XOR A
    LD B, 10                ; Clear all 10 bytes
INIT_SPAWNER_LOOP:
    LD (HL), A
    INC HL
    DJNZ INIT_SPAWNER_LOOP
    RET

INIT_SOUND:
    ; soundRef(2), volume(1), looping(1), playing(1), channel(1)
    XOR A
    LD (HL), A              ; soundRef low
    INC HL
    LD (HL), A              ; soundRef high
    INC HL
    LD (HL), 255            ; volume = max
    INC HL
    LD (HL), A              ; looping = false
    INC HL
    LD (HL), A              ; playing = false
    INC HL
    LD (HL), A              ; channel = 0
    RET

INIT_POWERUP:
    ; powerupType(1), value(2), duration(2), permanent(1), collected(1), respawnTime(1)
    XOR A
    LD (HL), A              ; powerupType = 0
    INC HL
    LD (HL), 1              ; value low = 1
    INC HL
    LD (HL), A              ; value high = 0
    INC HL
    LD (HL), A              ; duration low = 0 (permanent)
    INC HL
    LD (HL), A              ; duration high = 0
    INC HL
    LD (HL), 1              ; permanent = true
    INC HL
    LD (HL), A              ; collected = false
    INC HL
    LD (HL), A              ; respawnTime = 0
    RET

INIT_DIALOG:
    ; textRef(2), active(1), currentChar(2), speed(1), autoClose(1), closeDelay(1)
    XOR A
    LD (HL), A              ; textRef low
    INC HL
    LD (HL), A              ; textRef high
    INC HL
    LD (HL), A              ; active = false
    INC HL
    LD (HL), A              ; currentChar low = 0
    INC HL
    LD (HL), A              ; currentChar high = 0
    INC HL
    LD (HL), 2              ; speed = 2 chars per frame
    INC HL
    LD (HL), A              ; autoClose = false
    INC HL
    LD (HL), 60             ; closeDelay = 1 second
    RET

INIT_TRIGGER:
    ; triggerType(1), active(1), triggered(1), resetTime(2), targetEntity(2), actionData(3)
    XOR A
    LD (HL), A              ; triggerType = 0
    INC HL
    LD (HL), 1              ; active = true
    INC HL
    LD (HL), A              ; triggered = false
    INC HL
    LD B, 7                 ; Clear remaining 7 bytes
INIT_TRIGGER_LOOP:
    LD (HL), A
    INC HL
    DJNZ INIT_TRIGGER_LOOP
    RET